function KpiCard({ label, value, icon: Icon, tone, caption }: { label: string; value: number; icon: typeof CircleDollarSign; tone: "navy" | "teal" | "amber" | "rose" | "slate" | "indigo"; caption: string }) {
  return <Card className="kpi-card"><CardContent className="p-5"><div className="flex items-start justify-between gap-3"><div><p className="kpi-label">{label}</p><p className="kpi-value">{money(value)}</p></div><div className={`kpi-icon ${tone}`}><Icon /></div></div><p className="kpi-caption">{caption}</p></CardContent></Card>;
}

function useCurrentRange(period: string) {
  return useMemo(() => {
    const year = new Date().getFullYear();
    const range = (start: Date, end: Date) => ({ start: start.getTime(), end: end.getTime() });
    if (period === "Q1") return range(new Date(year, 0, 1), new Date(year, 2, 31, 23, 59, 59));
    if (period === "Q2") return range(new Date(year, 3, 1), new Date(year, 5, 30, 23, 59, 59));
    if (period === "Q3") return range(new Date(year, 6, 1), new Date(year, 8, 30, 23, 59, 59));
    if (period === "Q4") return range(new Date(year, 9, 1), new Date(year, 11, 31, 23, 59, 59));
    if (period === "6TĐN") return range(new Date(year, 0, 1), new Date(year, 5, 30, 23, 59, 59));
    if (period === "6TCN") return range(new Date(year, 6, 1), new Date(year, 11, 31, 23, 59, 59));
    if (period === "Năm") return range(new Date(year, 0, 1), new Date(year, 11, 31, 23, 59, 59));
    return undefined;
  }, [period]);
}

